contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address newOwner) public payable {
        require(true);

        // Read owner before the call
        address before = c.owner(); if (__ESBMC_reverted()) return;

        // Call setOwner and capture revert/return
        bool reverted;
        bool returnedTrue;
        bool ok = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            returnedTrue = false;
        } else {
            reverted = false;
            returnedTrue = ok;
        }

        // Read owner after the call
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: if this contract was the owner before the call, then the call must not revert,
        // must return true, and owner() must equal the provided newOwner.
        assert((before != address(this)) || (!reverted && returnedTrue && afterOwner == newOwner));
    }

    receive() external payable {}
}

